def find_path(graph, start, goal):
    visited = set()  # Set to keep track of visited nodes
    path_stack = [(start, [start])]  # Stack to keep track of paths

    while path_stack:
        (vertex, path) = path_stack.pop()  # Pop path from stack
        if vertex not in visited:
            visited.add(vertex)  # Mark vertex as visited
            if vertex == goal:
                return path  # If goal is reached, return the path
            neighbours = graph.get(vertex, [])
            for next_vertex in neighbours:
                if next_vertex not in visited:
                    new_path = path + [next_vertex]
                    path_stack.append((next_vertex, new_path))
    return None  # Return None if goal is unreachable
