def find_path(graph, start, goal):
    # Initialize the path list and the visited set
    path = [start]
    visited = set([start])

    # Keep searching until we reach the goal or all paths are exhausted
    while path and path[-1] != goal:
        # Get the last node in the path
        current_node = path[-1]
        # Get the neighbors of the current node
        for neighbor in graph[current_node]:
            # If the neighbor has not been visited, add it to the path
            if neighbor not in visited:
                visited.add(neighbor)
                path.append(neighbor)
                break
        else:
            # If the neighbor is not found in the current path, backtrack
            path.pop()
            if path:
                current_node = path[-1]
            else:
                # If the path is exhausted and we haven't reached the goal, backtrack further
                while path:
                    current_node = path.pop()
                    if current_node in graph:
                        break
                else:
                    return None
    return path
