def find_path(graph, start, goal):
    # Initialize the paths dictionary with None for all nodes
    paths = {node: None for node in graph}
    # Initialize the path record dictionary with None for all nodes
    path_records = {node: None for node in graph}

    # Define the recursive helper function
    def _find_path(current_node, goal):
        # If the goal node is reached, reconstruct the path
        if current_node == goal:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = path_records[current_node]
            return path[::-1]

        # If the path has already been computed, return it
        if paths[current_node] is not None:
            return paths[current_node]

        # Compute the path
        paths[current_node] = _find_path(current_node, goal)
        for neighbor in graph[current_node]:
            if paths[neighbor] is None:
                # Keep track of the path to the neighbor
                path_records[neighbor] = current_node
                # Recursively find the path to the neighbor
                paths[neighbor] = _find_path(neighbor, goal)

        return paths[current_node]

    # Start the search
    return _find_path(start, goal)
