def find_path(graph, start, goal):
    # Initialize the path and the set of seen nodes
    path = []
    seen = set()

    # Keep track of the path we're currently building
    def search(node):
        if node not in seen:
            path.append(node)
            seen.add(node)
            if node == goal:
                return path
            for neighbor in graph.get(node, []):
                if neighbor not in seen:
                    result = search(neighbor)
                    if result is not None: 
                        return result
            path.pop()  # Remove the last node if the path to the goal does not include it
        return None

    path = search(start)
    return path if path else None
