def find_path(graph, start, goal):
    # Initialize the set of visited nodes and the path
    visited = set()
    path = []

    # List to hold the order of nodes in the path
    path_order = []

    # Function to perform breadth-first search
    def bfs():
        queue = [(start, [start])]
        while queue:
            (node, path) = queue.pop(0)
            if node not in visited:
                visited.add(node)
                if node == goal:
                    return path
                queue.extend((neighbor, path + [neighbor]) for neighbor in graph[node] if neighbor not in visited)
        return None

    # Perform BFS and get the path
    path = bfs()

    # If path is found, reconstruct the order of nodes
    if path:
        for node in path:
            if node not in visited:
                path_order.append(node)
        path_order.append(goal)
        return path_order
    else:
        return None
