from collections import deque

def find_path(graph, start, goal):
    # List to hold the path
    path = []
    # Queue for BFS (we always visit a node only after the whole neighborhood has been explored)
    queue = deque([(start, [start])])  # Node and path tuple

    while queue:
        (vertex, path) = queue.popleft()

        for next_vertex in graph[vertex]:
            if next_vertex not in path:
                # If the next_vertex is the goal, we found the path
                if next_vertex == goal:
                    path.append(goal)
                    return path
                else:
                    queue.append((next_vertex, path + [next_vertex]))

    # If we reached here, it means the goal is unreachable
    return None
